std::string wide_to_utf8(const std::wstring& value) {
    if (value.empty()) return {};
    const auto size = WideCharToMultiByte(
        CP_UTF8, WC_ERR_INVALID_CHARS, value.data(), static_cast<int>(value.size()),
        nullptr, 0, nullptr, nullptr);
    if (size <= 0) throw std::runtime_error("could not encode UTF-16 path as UTF-8");
    std::string out(static_cast<std::size_t>(size), '\0');
    if (WideCharToMultiByte(
            CP_UTF8, WC_ERR_INVALID_CHARS, value.data(), static_cast<int>(value.size()),
            out.data(), size, nullptr, nullptr) != size) {
        throw std::runtime_error("could not encode UTF-16 path as UTF-8");
    }
    return out;
}

std::wstring utf8_to_wide(const std::string& value) {
    if (value.empty()) return {};
    const auto size = MultiByteToWideChar(
        CP_UTF8, MB_ERR_INVALID_CHARS, value.data(), static_cast<int>(value.size()),
        nullptr, 0);
    if (size <= 0) throw std::runtime_error("path is not valid UTF-8");
    std::wstring out(static_cast<std::size_t>(size), L'\0');
    if (MultiByteToWideChar(
            CP_UTF8, MB_ERR_INVALID_CHARS, value.data(), static_cast<int>(value.size()),
            out.data(), size) != size) {
        throw std::runtime_error("path is not valid UTF-8");
    }
    return out;
}

std::string windows_error(const char* operation, DWORD code = GetLastError()) {
    wchar_t* raw = nullptr;
    const auto length = FormatMessageW(
        FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM |
            FORMAT_MESSAGE_IGNORE_INSERTS,
        nullptr, code, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
        reinterpret_cast<wchar_t*>(&raw), 0, nullptr);
    std::wstring detail = length && raw ? std::wstring(raw, length) : L"unknown error";
    if (raw) LocalFree(raw);
    while (!detail.empty() &&
           (detail.back() == L'\r' || detail.back() == L'\n' || detail.back() == L' ')) {
        detail.pop_back();
    }
    return std::string(operation) + " failed (Windows " + std::to_string(code) + "): " +
        wide_to_utf8(detail);
}

bool missing_error(DWORD code) {
    return code == ERROR_FILE_NOT_FOUND || code == ERROR_PATH_NOT_FOUND;
}

bool ensure_directories(const std::wstring& path, std::string& error) {
    if (path.empty()) {
        error = "directory path is empty";
        return false;
    }

    std::size_t start = 0;
    if (path.size() >= 3 && path[1] == L':' &&
        (path[2] == L'\\' || path[2] == L'/')) {
        start = 3;
    }
    for (std::size_t pos = path.find_first_of(L"\\/", start);
         pos != std::wstring::npos;
         pos = path.find_first_of(L"\\/", pos + 1)) {
        const auto prefix = path.substr(0, pos);
        if (prefix.empty()) continue;
        if (!CreateDirectoryW(prefix.c_str(), nullptr) && GetLastError() != ERROR_ALREADY_EXISTS) {
            error = windows_error("CreateDirectoryW");
            return false;
        }
    }
    if (!CreateDirectoryW(path.c_str(), nullptr) && GetLastError() != ERROR_ALREADY_EXISTS) {
        error = windows_error("CreateDirectoryW");
        return false;
    }
    return true;
}

std::wstring executable_directory() {
    std::vector<wchar_t> buffer(512);
    for (;;) {
        const auto length = GetModuleFileNameW(
            nullptr, buffer.data(), static_cast<DWORD>(buffer.size()));
        if (length == 0) throw std::runtime_error(windows_error("GetModuleFileNameW"));
        if (length < buffer.size() - 1) {
            std::wstring path(buffer.data(), length);
            const auto slash = path.find_last_of(L"\\/");
            if (slash == std::wstring::npos) {
                throw std::runtime_error("game executable has no parent directory");
            }
            return path.substr(0, slash);
        }
        buffer.resize(buffer.size() * 2);
    }
}

bool valid_relative_path(const std::string& relative, std::string& error) {
    if (relative.size() < 9 || relative.size() > 4096 ||
        relative.compare(0, 8, "fgcnote/") != 0) {
        error = "path must be below fgcnote/";
        return false;
    }
    if (relative.find('\\') != std::string::npos ||
        relative.find(':') != std::string::npos ||
        relative.front() == '/') {
